param([Parameter(Mandatory=$true)][string]$ExportRoot,[string]$DataRoot='C:\ProgramData\{{SERVICE}}',[string]$TaskName='{{SERVICE}} Service')
$ErrorActionPreference='Stop';$manifest=Get-Content -Raw "$ExportRoot\{{KIND}}-data-manifest.json"|ConvertFrom-Json;foreach($entry in $manifest.files){$path=Join-Path $ExportRoot $entry.path;if((Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.sha256){throw "Export hash mismatch: $($entry.path)"}}
$staging="$DataRoot\data-import";if(Test-Path $staging){Remove-Item $staging -Recurse -Force};New-Item -ItemType Directory -Force -Path $staging|Out-Null;Copy-Item "$ExportRoot\{{KIND}}\*" $staging -Recurse -Force
$actual=(Get-ChildItem $staging -File -Recurse).Count;if($actual -ne $manifest.file_count){throw "Import count mismatch: expected $($manifest.file_count), found $actual"};Stop-ScheduledTask $TaskName -ErrorAction SilentlyContinue;$stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ');Move-Item "$DataRoot\data" "$DataRoot\backups\data-$stamp";Move-Item $staging "$DataRoot\data";Start-ScheduledTask $TaskName -ErrorAction SilentlyContinue
[ordered]@{imported=$true;service='{{KIND}}';file_count=$actual;source_manifest="$ExportRoot\{{KIND}}-data-manifest.json"}|ConvertTo-Json
